function flagSuspicious(payments: string[]): string[] {
  const rows = payments.map(p => {
    const [name, t, amt, city] = p.split(",");
    return { name, t: Number(t), amt: Number(amt), city };
  });
  const flagged = rows.map(x => x.amt > 1000);
  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i], b = rows[j];
      if (a.name === b.name && a.city !== b.city && Math.abs(a.t - b.t) <= 60) {
        flagged[i] = true;
        flagged[j] = true;
      }
    }
  }
  return payments.filter((_, i) => flagged[i]);
}

