function flagSuspicious(payments: string[]): string[] {
  const rows = payments.map(p => {
    const [name, t, amt, city] = p.split(",");
    return { name, t: Number(t), amt: Number(amt), city };
  });
  const seen = new Map<string, Map<number, Set<string>>>();
  for (const { name, t, city } of rows) {
    if (!seen.has(name)) seen.set(name, new Map());
    const byMinute = seen.get(name)!;
    if (!byMinute.has(t)) byMinute.set(t, new Set());
    byMinute.get(t)!.add(city);
  }
  return payments.filter((_, i) => {
    const { name, t, amt, city } = rows[i];
    if (amt > 1000) return true;
    const byMinute = seen.get(name)!;
    for (let m = t - 60; m <= t + 60; m++) {
      const cities = byMinute.get(m);
      // a set with another city in it: size > 1, or one city that isn't ours
      if (cities && (cities.size > 1 || !cities.has(city))) return true;
    }
    return false;
  });
}

